def classify(name, parameters=None):
    parameters = parameters or {}
    writer = WRITERS.get(name)
    if name in {'parameters', 'tbounce.dat', 'list_of_restartfiles.txt'}:
        return 'metadata'
    if 'restart' in name.lower() or name.endswith(('.h5', '.hdf5')):
        return 'binary_or_restart'
    if writer == 'performance_table':
        return 'diagnostics'
    if writer in {'output_scalar', 'output_central', 'leakage_scalar'}:
        return 'series'
    if writer in {'output_many_scalars', 'output_accretion', 'leakage_many'}:
        return 'series'
    if writer == 'output_spectra':
        return 'spectra'
    if writer == 'mass_coordinate':
        return 'mass_profiles'
    if writer in {'leakage_multi', 'leakage_single', 'output_singlemod'}:
        return 'special_profiles'
    if name.endswith('.xg'):
        if parameters.get('vs_mass', '0').lower() in {'1', '.true.', 'true'} and name != 'mass_bary_at_bounce.xg':
            return 'mass_profiles'
        return 'profiles' if writer == 'output_single' else 'unknown'
    return 'unknown'


def series_schema(name):
    writer = WRITERS.get(name)
    return {'time_column': 1 if name == 'timers.dat' else 0,
            'requires_value_column': writer in {'output_many_scalars', 'output_accretion', 'leakage_many', 'performance_table'},
            'time_reference': 'postbounce' if writer in {'leakage_many', 'leakage_scalar'} else 'simulation'}
